python3 - <<'PY'
p='src/types/checker/functions/resolution/signature.rs'
s=open(p).read()
old = """/// Returns whether an array-ish type's ELEMENT representation widened to `Mixed`.
///
/// The container kind has to match: an `Array` that became an `AssocArray` is a different
/// change, already carried by the ordinary storage machinery.
fn array_element_widens_to_mixed(entry: &PhpType, exit: &PhpType) -> bool {
    match (entry.codegen_repr(), exit.codegen_repr()) {
        (PhpType::Array(entry_elem), PhpType::Array(exit_elem)) => {
            entry_elem.codegen_repr() != PhpType::Mixed
                && exit_elem.codegen_repr() == PhpType::Mixed
        }
        (
            PhpType::AssocArray {
                value: entry_value, ..
            },
            PhpType::AssocArray {
                value: exit_value, ..
            },
        ) => {
            entry_value.codegen_repr() != PhpType::Mixed
                && exit_value.codegen_repr() == PhpType::Mixed
        }
        _ => false,
    }
}"""
new = """/// Returns whether an array-ish type's ELEMENT representation CHANGED across the body.
///
/// Any change matters, not only a widening to `Mixed`: an empty `array<never>` that the body
/// appends ints to becomes `array<int>`, and the caller keeps its own pointer to the empty one
/// unless it is told. `never` on the way OUT is not a change — a body that only reads leaves the
/// element type where the checker's join put it.
///
/// The container kind has to match: an `Array` that became an `AssocArray` is a different change,
/// already carried by the ordinary storage machinery.
fn array_element_representation_changes(entry: &PhpType, exit: &PhpType) -> bool {
    match (entry.codegen_repr(), exit.codegen_repr()) {
        (PhpType::Array(entry_elem), PhpType::Array(exit_elem)) => {
            exit_elem.codegen_repr() != PhpType::Never
                && entry_elem.codegen_repr() != exit_elem.codegen_repr()
        }
        (
            PhpType::AssocArray {
                value: entry_value, ..
            },
            PhpType::AssocArray {
                value: exit_value, ..
            },
        ) => {
            exit_value.codegen_repr() != PhpType::Never
                && entry_value.codegen_repr() != exit_value.codegen_repr()
        }
        _ => false,
    }
}"""
assert s.count(old)==1
s=s.replace(old,new)
s=s.replace("            if !array_element_widens_to_mixed(entry_ty, exit_ty) {",
            "            if !array_element_representation_changes(entry_ty, exit_ty) {")
open(p,'w').write(s)
